def transform(grid):
    h,w=len(grid),len(grid[0])
    cells=[(r,c) for r in range(h) for c in range(w) if grid[r][c]]
    r0=min(r for r,c in cells); r1=max(r for r,c in cells)
    c0=min(c for r,c in cells); c1=max(c for r,c in cells)
    color=grid[r0][c0]
    out=[[0]*w for _ in range(h)]
    for r,c in cells:
        # translate all intermediate contours by a progressively increasing amount;
        # top edge shifts fully to the left while bottom stays fixed.
        if r==r0:
            nc=c-c0
        elif r==r1:
            nc=c
        else:
            nc=c-(c0 + (r-r0))
        if 0<=nc<w: out[r][nc]=color
    return out
